import React, { useState, useMemo, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

// The query caps at the 1000 most recent instances; say so rather than implying
// this is the full population for a high-volume code.
const CAP = 1000;
const COLS = [
  { key: "Bill Id", label: "Bill Id" },
  { key: "Billing ID", label: "Billing ID" },
  { key: "Vendor", label: "Vendor" },
  { key: "Invoice Date", label: "Invoice Date" },
  { key: "Utility", label: "Utility" },
  { key: "Account", label: "Account" },
  { key: "Meter", label: "Meter" },
  { key: "Severity", label: "Severity" },
  { key: "Message", label: "Message", wrap: 520 },
  { key: "Resolved", label: "Resolved" },
  { key: "Raised", label: "Raised" }
];

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [res, setRes] = useState("");
  const [q, setQ] = useState("");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];
  const code = model.code == null ? "" : String(model.code);
  const cat = model.category || "";
  const name = model.name || "";

  const rows = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return data.filter((r) => {
      if (res === "open" && r["Resolved"]) return false;
      if (res === "resolved" && !r["Resolved"]) return false;
      if (!needle) return true;
      return ["Bill Id", "Billing ID", "Account", "Meter", "Message"].some((k) =>
        String(r[k] == null ? "" : r[k]).toLowerCase().indexOf(needle) !== -1);
    });
  }, [data, res, q]);

  useEffect(() => { setPage(1); }, [rows.length]);

  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const pageRows = rows.slice((safePage - 1) * pageSize, (safePage - 1) * pageSize + pageSize);
  const close = () => { if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent("onClose"); };

  const cell = (r, c) => {
    if (c.key === "Severity") {
      const t = r["Severity"] == null ? "" : String(r["Severity"]);
      return t ? React.createElement("span", { className: "badge b-sev" + (r.severity_code || 20) }, t) : "";
    }
    if (c.key === "Resolved") {
      return r["Resolved"]
        ? React.createElement("span", { className: "badge b-info" }, "Resolved")
        : React.createElement("span", { className: "badge b-error" }, "Open");
    }
    const v = r[c.key];
    return v == null || v === "" ? React.createElement("span", { className: "empty" }, "—") : String(v);
  };

  const head = React.createElement("div", { className: "hd" },
    React.createElement("div", { className: "t" },
      React.createElement("h2", null, code ? "Code " + code + (cat ? "  ·  " + cat : "") : "Bill errors"),
      React.createElement("div", { className: "s" }, name)),
    React.createElement("button", { className: "x", onClick: close, title: "Close" }, "×"));

  if (model.isLoading)
    return React.createElement("div", { className: "wrap" }, head,
      React.createElement("div", { className: "skel" }, "Loading affected bills..."));

  return React.createElement("div", { className: "wrap" }, head,
    React.createElement("div", { className: "bar" },
      React.createElement("div", { className: "fld" },
        React.createElement("label", null, "Status"),
        React.createElement("select", { value: res, onChange: (e) => setRes(e.target.value) },
          React.createElement("option", { value: "" }, "All"),
          React.createElement("option", { value: "open" }, "Open"),
          React.createElement("option", { value: "resolved" }, "Resolved"))),
      React.createElement("div", { className: "fld" },
        React.createElement("label", null, "Search bill, account, meter or message"),
        React.createElement("input", { value: q, onChange: (e) => setQ(e.target.value), placeholder: "Search" }))),
    data.length >= CAP
      ? React.createElement("div", { className: "cap" },
          "Showing the " + CAP.toLocaleString() + " most recent instances; narrow the date range to see earlier ones.")
      : null,
    React.createElement("div", { className: "meta" }, rows.length + " of " + data.length + " shown"),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null, COLS.map((c) => React.createElement("th", { className: "noSort", key: c.key }, c.label)))),
        React.createElement("tbody", null,
          pageRows.length === 0
            ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: COLS.length }, "No bills match"))
            : pageRows.map((r, i) => React.createElement("tr", { key: i },
                COLS.map((c) => React.createElement("td", { key: c.key },
                  c.wrap ? React.createElement("div", { style: { maxWidth: c.wrap + "px" } }, cell(r, c)) : cell(r, c)))))))),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => setPage(safePage - 1) }, "‹"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("span", { className: "gotolbl" }, "of " + totalPages),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => setPage(safePage + 1) }, "›"),
      React.createElement("select", { className: "psize", value: pageSize,
        onChange: (e) => { setPageSize(Number(e.target.value)); setPage(1); } },
        [10, 20, 50, 100].map((n) => React.createElement("option", { key: n, value: n }, n + "/page")))));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

